def clean_text(text):
    if not isinstance(text, str):
        return ""
    text = text.lower()
    text = re.sub(r'\[.*?\]', '', text)
    text = re.sub(r'[^a-z\s]', '', text)
    try:
        stop_words = set(stopwords.words('english'))
    except LookupError:
        nltk.download('stopwords')
        stop_words = set(stopwords.words('english'))
    tokens = word_tokenize(text)
    tokens = [word for word in tokens if word not in stop_words and len(word) > 2]
    return ' '.join(tokens)

def process_data(df):
    df = df.copy()
    df.drop_duplicates(subset=['Keyword'], keep='first', inplace=True)
    df.dropna(subset=['Transcript', 'Views', 'Likes', 'Comments'], inplace=True)
    df['Date Released'] = pd.to_datetime(df['Date Released'], errors='coerce')
    df.dropna(subset=['Date Released'], inplace=True)
    df = df[(df['Date Released'].dt.year >= 2010) & (df['Date Released'].dt.year <= 2025)]
    df['year'] = df['Date Released'].dt.year
    bins = [2010, 2014, 2019, 2025]
    labels = ['2010-2014', '2015-2019', '2020-2025']
    df['period'] = pd.cut(df['year'], bins=bins, labels=labels, right=True, include_lowest=True)
    df.dropna(subset=['period'], inplace=True)
    df['engagement_score'] = df['Views'] + df['Likes'] + df['Comments']
    df['clean_transcript'] = df['Transcript'].apply(clean_text)
    df = df[df['clean_transcript'].str.strip() != '']
    return df

def render_sidebar():
    with st.sidebar:
        st.title("Data Source")
        uploaded_file = st.file_uploader("Upload Dataset", type=['csv', 'xlsx'], label_visibility="collapsed")
        use_example = st.checkbox("Use example dataset (if no upload)")
        
        data = None
        if uploaded_file is not None:
            try:
                if uploaded_file.name.endswith('.csv'):
                    data = pd.read_csv(uploaded_file)
                else:
                    data = pd.read_excel(uploaded_file)
            except Exception as e:
                st.error(f"Error loading file: {e}")
        elif use_example:
            data = load_example_data()
        
        if data is None:
            st.info("Awaiting data. Please upload a file or check the example dataset box.")
            st.stop()
        
        return data

def main():
    st.markdown("<h1>TEDx Talk Engagement Analysis</h1>", unsafe_allow_html=True)
    st.markdown("<h3>A five-year period analysis of audience engagement, topics, and trends (2010-2025)</h3>", unsafe_allow_html=True)

    raw_df = render_sidebar()

    required_cols = ['Keyword', 'Speaker', 'Date Released', 'Views', 'Likes', 'Comments', 'Transcript']
    if not all(col in raw_df.columns for col in required_cols):
        st.error(f"Dataset is missing one or more required columns: {required_cols}")
        st.stop()

    df = process_data(raw_df)

    if df.empty:
        st.error("No data available after applying filtering rules. Please check your dataset against the scope criteria (2010-2025, English transcripts, valid engagement metrics).")
        st.stop()

    tab1, tab2, tab3, tab4, tab5 = st.tabs([
        "Engagement Levels by Period",
        "Keyword and Theme Patterns",
        "Topic Clusters and Engagement",
        "Period Variations and Trends",
        "Top Performing Content"
    ])

    with tab1:
        st.header("Audience Engagement Analysis")
        st.write("Aggregate audience engagement metrics for each five-year period.")
        
        period_agg = df.groupby('period', observed=True).agg(
            Videos=('Keyword', 'count'),
            Views=('Views', 'sum'),
            Likes=('Likes', 'sum'),
            Comments=('Comments', 'sum'),
            Avg_Engagement=('engagement_score', 'mean'),
            Total_Engagement=('engagement_score', 'sum')
        ).reset_index()
        
        st.dataframe(period_agg.style.format({
            'Videos': '{:,}',
            'Views': '{:,}',
            'Likes': '{:,}',
            'Comments': '{:,}',
            'Avg_Engagement': '{:,.0f}',
            'Total_Engagement': '{:,.0f}'
        }), use_container_width=True)

        st.subheader("Total Engagement Score by Period")
        st.bar_chart(period_agg.set_index('period')['Total_Engagement'], use_container_width=True)

        st.subheader("Average Engagement Score per Video by Period")
        st.bar_chart(period_agg.set_index('period')['Avg_Engagement'], use_container_width=True)
        
        st.subheader("Individual Engagement Metrics by Period")
        st.bar_chart(period_agg.set_index('period')[['Views', 'Likes', 'Comments']], use_container_width=True)

    with tab2:
        st.header("Content Identification via Text Mining")
        st.write("Most frequent terms and recurring bigrams from cleaned transcripts across all periods.")

        all_text = ' '.join(df['clean_transcript'])
        tokens = all_text.split()
        word_freq = Counter(tokens).most_common(25)
        freq_df = pd.DataFrame(word_freq, columns=['Term', 'Frequency']).set_index('Term')
        
        st.subheader("Top 25 Most Frequent Keywords")
        st.dataframe(freq_df.T, use_container_width=True)
        st.bar_chart(freq_df, use_container_width=True)

        st.subheader("Top 20 Recurring Bigrams (Themes)")
        bigrams = list(zip(tokens[:-1], tokens[1:]))
        bigram_freq = Counter(bigrams).most_common(20)
        bigram_df = pd.DataFrame(bigram_freq, columns=['Bigram', 'Frequency'])
        bigram_df['Bigram'] = bigram_df['Bigram'].apply(lambda x: f"{x[0]} {x[1]}")
        st.dataframe(bigram_df.set_index('Bigram').T, use_container_width=True)
        st.bar_chart(bigram_df.set_index('Bigram'), use_container_width=True)

    with tab3:
        st.header("Topic Modeling and Engagement")
        st.write("Non-Negative Matrix Factorization (NMF) identifies latent topics; engagement is compared across these clusters.")

        num_topics = min(5, len(df))
        if len(df) < 2:
            st.warning("Insufficient data for topic modeling. At least 2 videos required.")
        else:
            tfidf_vectorizer = TfidfVectorizer(max_df=0.95, min_df=1, stop_words='english')
            tfidf = tfidf_vectorizer.fit_transform(df['clean_transcript'])
            
            nmf = NMF(n_components=num_topics, random_state=42, init='nndsvda', max_iter=500)
            nmf_features = nmf.fit_transform(tfidf)
            
            feature_names = tfidf_vectorizer.get_feature_names_out()
            
            topic_keywords = {}
            for topic_idx, topic in enumerate(nmf.components_):
                top_features = [feature_names[i] for i in topic.argsort()[:-10 - 1:-1]]
                topic_keywords[f"Topic {topic_idx+1}"] = ", ".join(top_features)
            
            st.subheader("Identified Topics and Keywords")
            st.dataframe(pd.DataFrame.from_dict(topic_keywords, orient='index', columns=['Top Keywords']), use_container_width=True)

            df['topic_cluster'] = nmf_features.argmax(axis=1)
            df['topic_label'] = df['topic_cluster'].apply(lambda x: f"Topic {x+1}")

            topic_agg = df.groupby('topic_label').agg(
                Videos=('Keyword', 'count'),
                Total_Engagement=('engagement_score', 'sum'),
                Avg_Engagement=('engagement_score', 'mean')
            ).reset_index().rename(columns={'topic_label': 'Topic'})

            st.subheader("Engagement Metrics by Topic Cluster")
            st.dataframe(topic_agg.style.format({
                'Videos': '{:,}',
                'Total_Engagement': '{:,.0f}',
                'Avg_Engagement': '{:,.0f}'
            }), use_container_width=True)
            
            st.subheader("Average Engagement Score by Topic")
            st.bar_chart(topic_agg.set_index('Topic')['Avg_Engagement'], use_container_width=True)

    with tab4:
        st.header("Trend Analysis Across Periods")
        st.write("Period-over-period changes in aggregate engagement and topic composition.")

        pivot_engagement = df.pivot_table(index='period', values=['Views', 'Likes', 'Comments', 'engagement_score'], aggfunc='sum', observed=True)
        st.subheader("Aggregate Metrics Over Time")
        st.dataframe(pivot_engagement.style.format('{:,.0f}'), use_container_width=True)
        
        st.subheader("Growth in Engagement Score")
        if len(pivot_engagement) > 1:
            growth = pivot_engagement['engagement_score'].pct_change() * 100
            growth_df = pd.DataFrame({'Period': growth.index, 'Growth (%)': growth.values})
            st.dataframe(growth_df.style.format({'Growth (%)': '{:,.1f}%'}), use_container_width=True)
            st.bar_chart(growth_df.set_index('Period'), use_container_width=True)
        else:
            st.info("At least two periods required to compute growth.")

        if 'topic_label' in df.columns:
            st.subheader("Topic Share Over Time")
            topic_share = df.groupby(['period', 'topic_label'], observed=True).size().unstack(fill_value=0)
            topic_share_pct = topic_share.div(topic_share.sum(axis=1), axis=0) * 100
            st.dataframe(topic_share_pct.style.format('{:.1f}%'), use_container_width=True)
            st.bar_chart(topic_share_pct, use_container_width=True)

    with tab5:
        st.header("Top Performing Content by Period")
        st.write("Top 3 videos by engagement score within each five-year period.")

        top_videos = df.sort_values('engagement_score', ascending=False).groupby('period', observed=True).head(3)
        
        for period in df['period'].unique():
            st.subheader(f"Period: {period}")
            period_top = top_videos[top_videos['period'] == period]
            for idx, row in period_top.iterrows():
                with st.expander(f"{row['Keyword']} — {row['Speaker']}"):
                    col1, col2, col3, col4 = st.columns(4)
                    col1.metric("Views", f"{row['Views']:,}")
                    col2.metric("Likes", f"{row['Likes']:,}")
                    col3.metric("Comments", f"{row['Comments']:,}")
                    col4.metric("Engagement Score", f"{row['engagement_score']:,}")

        st.subheader("Statistical Comparison of Topic Engagement")
        if 'topic_label' in df.columns and df['topic_label'].nunique() > 1:
            groups = [group['engagement_score'].values for name, group in df.groupby('topic_label')]
            if all(len(g) > 0 for g in groups):
                try:
                    stat, p_value = kruskal(*groups)
                    st.metric("Kruskal-Wallis H-test p-value", f"{p_value:.4f}")
                    if p_value < 0.05:
                        st.write("The difference in engagement scores across topic clusters is statistically significant (p < 0.05).")
                    else:
                        st.write("No statistically significant difference in engagement scores across topic clusters (p >= 0.05).")
                except ValueError:
                    st.warning("Unable to perform Kruskal-Wallis test: all topic groups must have at least one sample.")
            else:
                st.warning("Insufficient data for statistical test.")
        else:
            st.info("Topic modeling required for statistical comparison. Upload more data or use the example dataset.")

if __name__ == "__main__":
    main()
